fn build_order(jobs: List[Job]) -> Result[List[String], String] {
  let job_map = jobs
    |> map(|j| (j.name, j.deps))
    |> map_from();

  let mut order = [];
  let mut placed = [];
  let mut remaining = jobs;

  while remaining.len() > 0 {
    let mut next = null;
    for j in remaining {
      if j.deps
        |> filter(|d| !placed.contains(d))
        |> len() == 0
      {
        next = j;
        break;
      }
    }

    if next == null {
      return Err("cycle detected");
    }

    order = order.append(next.name);
    placed = placed.append(next.name);
    remaining = remaining.filter(|j| j.name != next.name);
  }

  Ok(order)
}

