fn invoice_total(lines: List[Line], coupon: String) -> Result[Int, String] {
  if lines.is_empty() {
    return Ok(0);
  }

  let mut subtotal = 0;
  for line in lines {
    if line.qty < 1 {
      return Err(format!("bad quantity: {}", line.sku));
    }
    let amount = line.qty * line.unit_cents;
    if line.qty >= 10 {
      amount -= amount / 10;
    }
    subtotal += amount;
  }

  let mut amount = subtotal;
  match coupon.as_str() {
    "" => (),
    "SAVE500" => amount = amount.saturating_sub(500),
    "PCT10" => amount -= amount / 10,
    "BIG20" if subtotal >= 10000 => amount -= amount / 5,
    _ => return Err(format!("unknown coupon: {}", coupon)),
  }

  let tax = (amount * 8 + 50) / 100;
  amount += tax;
  Ok(amount)
}

