class Job(TypedDict):
    name: str
    deps: list[str]

def build_order(jobs: list[Job]) -> Ok[list[str]] | Err:
    job_set = set(job['name'] for job in jobs)
    if len(job_set) != len(jobs):
        first_duplicate = next(job['name'] for job in jobs if jobs.count(job) > 1)
        return Err({"ok": False, "error": f"duplicate job: {first_duplicate}"})

    graph = {job['name']: job['deps'] for job in jobs}
    in_degree = {job['name']: 0 for job in jobs}
    for job in jobs:
        for dep in job['deps']:
            if dep not in job_set:
                return Err({"ok": False, "error": f"unknown dependency: {dep}"})
            in_degree[dep] += 1

    queue = [job for job in jobs if in_degree[job['name']] == 0]
    result = []

    while queue:
        job = queue.pop(0)
        result.append(job['name'])
        for dep in graph[job['name']]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                queue.append(next(j for j in jobs if j['name'] == dep))

    if len(result) != len(jobs):
        return Err({"ok": False, "error": "cycle detected"})

    return Ok({"ok": True, "value": result})

