  if str_len(s) == 0 {
    return Err("empty".to_string());
  }

  let mut seconds = 0;
  let mut seen_units = 0;
  let mut i = 0;

  while i < str_len(s) {
    let mut num = 0;
    let mut j = i;

    while j < str_len(s) && s[j] >= '0' && s[j] <= '9' {
      num = num * 10 + (s[j] - '0' as u8) as Int;
      j += 1;
