def parse_duration(s: str) -> Ok[int] | Err:
    if not s:
        return Err(ok=False, error="empty")

    units = {'h': 3600, 'm': 60, 's': 1}
    result = 0
    i = 0

    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            number = int(s[i:j])
            if j == len(s):
                return Err(ok=False, error="missing unit")
            unit = s[j]
            if unit not in units:
                return Err(ok=False, error=f"unknown unit: {unit}")
            if j > i + 1 and s[i + 1:j].isdigit():
                return Err(ok=False, error=f"missing number before {unit}")
            if j > i + 1 and s[i:j - 1].isdigit():
                return Err(ok=False, error=f"unit out of order: {unit}")
            result += number * units[unit]
            i = j + 1
        else:
            return Err(ok=False, error=f"unknown unit: {s[i]}")

    return Ok(ok=True, value=result)

