Instr = Push | Pop | Add | Sub | Mul | Dup | Swap | Jz | Jmp | Print | Halt

def stack_vm(prog: list[Instr]) -> Ok[list[int]] | Err:
    stack: list[int] = []
    output: list[int] = []
    pc: int = 0
    steps: int = 0
    max_steps: int = 1000

    while pc < len(prog) and steps < max_steps:
        instr = prog[pc]
        steps += 1

        if instr["kind"] == "Push":
            stack.append(instr["n"])
        elif instr["kind"] == "Pop":
            if not stack:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            stack.pop()
        elif instr["kind"] == "Add":
            if len(stack) < 2:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            stack.append(stack.pop() + stack.pop())
        elif instr["kind"] == "Sub":
            if len(stack) < 2:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            stack.append(-stack.pop() + stack.pop())
        elif instr["kind"] == "Mul":
            if len(stack) < 2:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            stack.append(stack.pop() * stack.pop())
        elif instr["kind"] == "Dup":
            if not stack:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            stack.append(stack[-1])
        elif instr["kind"] == "Swap":
            if len(stack) < 2:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instr["kind"] == "Jz":
            if len(stack) < 1:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            if stack.pop() == 0:
                pc = instr["target"]
        elif instr["kind"] == "Jmp":
            pc = instr["target"]
        elif instr["kind"] == "Print":
            if not stack:
                return Err({"ok": False, "error": f"stack underflow at {pc}"})
            output.append(stack.pop())
        elif instr["kind"] == "Halt":
            break

    if steps >= max_steps:
        return Err({"ok": False, "error": "step limit exceeded"})

    return Ok({"ok": True, "value": output})

type Board = List[String]

fn tic_tac_toe(board: Board) -> String {
  let rows = board
  let cols = transpose(rows)
  let diags = [rows[0][0] + rows[1][1] + rows[2][2], rows[0][2] + rows[1][1] + rows[2][0]]
  let all_lines = rows ++ cols ++ diags

  let count_marks(line: String, mark: String) -> Int {
    return line.filter(|c| c == mark).len()
  }

  let count_x = all_lines.map(|line| count_marks(line, "X")).sum()
  let count_o = all_lines.map(|line| count_marks(line, "O")).sum()

  if abs(count_x - count_o) > 1 {
    return "invalid"
