def parse_money(s: str) -> Ok[int] | Err:
    if s.startswith('-'):
        s = s[1:]
        negate = True
    else:
        negate = False

    if not s.startswith('$'):
        return Err(error="missing $")

    s = s[1:]

    if '.' in s:
        dollars, cents = s.split('.', 1)
        if len(cents) != 2:
            return Err(error="bad cents")
    else:
        dollars = s
        cents = '00'

    if not dollars:
        return Err(error="bad dollars")

    if dollars[0] == '0' and len(dollars) > 1:
        return Err(error="bad dollars")

    if not dollars.replace(',', '').isdigit():
        return Err(error="bad dollars")

    dollars = dollars.replace(',', '')
    value = int(dollars) * 100 + int(cents)

    return Ok(value=value) if not negate else Err(error="negative value not allowed")

